import os
from openai import OpenAI
from openai import APIConnectionError, APIError, APITimeoutError, AuthenticationError, BadRequestError, InternalServerError, NotFoundError, PermissionDeniedError, RateLimitError
import json
import logging
import sys
from typing import Any

logging.basicConfig(level=os.environ.get("LOG_LEVEL", "INFO").upper(), format="%(asctime)s %(levelname)s %(name)s %(message)s")
logger = logging.getLogger("generalcompute_client")


def get_env_str(name: str, default: str | None = None, required: bool = False) -> str:
    value = os.environ.get(name, default)
    if value is None or value == "":
        if required:
            raise ValueError(f"Missing required environment variable: {name}")
        raise ValueError(f"Environment variable {name} is empty")
    return value


def get_env_int(name: str, default: int, minimum: int | None = None) -> int:
    raw_value = os.environ.get(name)
    value = default if raw_value in (None, "") else int(raw_value)
    if minimum is not None and value < minimum:
        raise ValueError(f"Environment variable {name} must be at least {minimum}")
    return value


def get_env_float(name: str, default: float, minimum: float | None = None, maximum: float | None = None) -> float:
    raw_value = os.environ.get(name)
    value = default if raw_value in (None, "") else float(raw_value)
    if minimum is not None and value < minimum:
        raise ValueError(f"Environment variable {name} must be at least {minimum}")
    if maximum is not None and value > maximum:
        raise ValueError(f"Environment variable {name} must be at most {maximum}")
    return value


def get_env_bool(name: str, default: bool) -> bool:
    raw_value = os.environ.get(name)
    if raw_value in (None, ""):
        return default
    normalized = raw_value.strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    raise ValueError(f"Environment variable {name} must be a boolean value")


def normalize_message(message: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(message, dict):
        raise ValueError("Each message must be an object")
    role = message.get("role")
    content = message.get("content")
    if not isinstance(role, str) or not role.strip():
        raise ValueError("Each message must include a non-empty string role")
    if isinstance(content, str):
        if not content:
            raise ValueError("Each message content string must be non-empty")
        return {"role": role, "content": content}
    if isinstance(content, list) and content:
        normalized_parts = []
        for part in content:
            if not isinstance(part, dict):
                raise ValueError("Each message content part must be an object")
            part_type = part.get("type")
            text = part.get("text")
            if part_type != "text" or not isinstance(text, str) or not text:
                raise ValueError("Each content part must be a text part with non-empty text")
            normalized_parts.append({"type": "text", "text": text})
        return {"role": role, "content": normalized_parts}
    raise ValueError("Each message must contain non-empty string content or a non-empty list of text parts")


def load_messages() -> list[dict[str, Any]]:
    raw_messages = os.environ.get("GENERALCOMPUTE_MESSAGES_JSON")
    if raw_messages:
        parsed = json.loads(raw_messages)
        if not isinstance(parsed, list) or not parsed:
            raise ValueError("GENERALCOMPUTE_MESSAGES_JSON must be a non-empty JSON array")
        return [normalize_message(message) for message in parsed]
    user_prompt = get_env_str("GENERALCOMPUTE_USER_PROMPT", default="Hello!")
    system_prompt = os.environ.get("GENERALCOMPUTE_SYSTEM_PROMPT", "")
    messages: list[dict[str, Any]] = []
    if system_prompt:
        messages.append({"role": "system", "content": system_prompt})
    messages.append({"role": "user", "content": user_prompt})
    return messages


def build_client() -> OpenAI:
    return OpenAI(
        api_key=get_env_str("GENERALCOMPUTE_API_KEY", required=True),
        base_url=get_env_str("GENERALCOMPUTE_BASE_URL", default=""),
        timeout=get_env_float("GENERALCOMPUTE_TIMEOUT_SECONDS", default=60.0, minimum=1.0),
        max_retries=get_env_int("GENERALCOMPUTE_MAX_RETRIES", default=3, minimum=0),
    )


def build_request_kwargs() -> tuple[dict[str, Any], bool]:
    request_kwargs: dict[str, Any] = {
        "model": get_env_str("GENERALCOMPUTE_MODEL", default="minimax-m2.7"),
        "messages": load_messages(),
        "max_completion_tokens": get_env_int("GENERALCOMPUTE_MAX_COMPLETION_TOKENS", default=1024, minimum=1),
        "temperature": get_env_float("GENERALCOMPUTE_TEMPERATURE", default=0.0, minimum=0.0, maximum=2.0),
    }
    stream = get_env_bool("GENERALCOMPUTE_STREAM", default=True)
    return request_kwargs, stream


def write_output(content: str) -> None:
    sys.stdout.write(content)
    if not content.endswith("\n"):
        sys.stdout.write("\n")
    sys.stdout.flush()


def extract_non_stream_content(response: Any) -> str:
    choices = getattr(response, "choices", None) or []
    if not choices:
        raise RuntimeError("The API response did not include any choices")
    message = getattr(choices[0], "message", None)
    if message is None:
        raise RuntimeError("The first choice did not include a message")
    content = getattr(message, "content", None)
    if not isinstance(content, str) or not content:
        raise RuntimeError("The first choice did not include non-empty text content")
    return content


def request_completion(client: OpenAI, request_kwargs: dict[str, Any], stream: bool) -> str:
    if not stream:
        response = client.chat.completions.create(**request_kwargs)
        content = extract_non_stream_content(response)
        write_output(content)
        return content
    collected: list[str] = []
    chunk_count = 0
    stream_response = client.chat.completions.create(**request_kwargs, stream=True)
    for chunk in stream_response:
        chunk_count += 1
        choices = getattr(chunk, "choices", None) or []
        if not choices:
            continue
        delta = getattr(choices[0], "delta", None)
        if delta is None:
            continue
        piece = getattr(delta, "content", None)
        if isinstance(piece, str) and piece:
            collected.append(piece)
            sys.stdout.write(piece)
            sys.stdout.flush()
    if not collected:
        if chunk_count == 0:
            raise RuntimeError("The streamed response did not include any chunks")
        raise RuntimeError("The streamed response did not include any text content")
    if not collected[-1].endswith("\n"):
        sys.stdout.write("\n")
        sys.stdout.flush()
    return "".join(collected)


def main() -> int:
    request_kwargs, stream = build_request_kwargs()
    client = build_client()
    request_completion(client, request_kwargs, stream)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except ValueError as exc:
        logger.error("Configuration error: %s", exc)
        raise SystemExit(2)
    except (AuthenticationError, PermissionDeniedError, NotFoundError, BadRequestError, RateLimitError, APITimeoutError, APIConnectionError, InternalServerError, APIError) as exc:
        logger.error("API request failed: %s: %s", exc.__class__.__name__, exc)
        raise SystemExit(1)
    except Exception as exc:
        logger.error("Unexpected error: %s: %s", exc.__class__.__name__, exc)
        raise SystemExit(1)
